def _mono_float(path: Path) -> tuple[int, np.ndarray]:
    fs, raw = wavfile.read(path)
    raw = np.asarray(raw)
    if raw.ndim > 1:
        x = np.mean(raw.astype(float), axis=1)
    else:
        x = raw.astype(float)
    if np.issubdtype(raw.dtype, np.integer):
        mx = np.iinfo(raw.dtype).max
        x = x / max(float(mx), 1.0)
    x = x - np.mean(x)
    norm = np.linalg.norm(x)
    return int(fs), x / norm if norm > 0 else x


def _excerpt(x: np.ndarray, N: int) -> np.ndarray:
    if len(x) >= N:
        start = (len(x) - N) // 2
        return x[start : start + N]
    y = np.zeros(N, float)
    y[: len(x)] = x
    return y


def fit_rate_with_quality(
    errors: np.ndarray, fraction: float = 0.35, floor: float = 1e-12
) -> Tuple[Optional[float], int, int, int, Optional[float], bool]:
    e = np.asarray(errors, float)
    idx = np.where(np.isfinite(e) & (e > floor))[0]
    idx = idx[idx >= 5]
    if len(idx) < 10:
        return None, 0, 0, 0, None, False

    n = max(10, int(np.ceil(fraction * len(idx))))
    sel = idx[-n:]
    x = sel
    y = np.log(e[sel])

    p, res, _, _, _ = np.polyfit(x, y, 1, full=True)
    slope = p[0]
    q_obs = float(np.exp(slope))

    # Calculate R^2 fit quality
    y_pred = slope * x + p[1]
    ss_tot = float(np.sum((y - np.mean(y)) ** 2))
    ss_res = float(np.sum((y - y_pred) ** 2))
    r2 = 1.0 - (ss_res / ss_tot) if ss_tot > 1e-15 else 1.0

    # Detect numerical floor
    floor_flag = bool(np.min(e[sel]) <= 1e-11 or (len(sel) >= 10 and np.std(e[sel[-10:]]) <= 1e-14))

    return q_obs, int(sel[0]), int(sel[-1]), int(n), float(max(0.0, min(1.0, r2))), floor_flag


def bootstrap_median_ci(data: List[float], num_bootstraps: int = 10000, alpha: float = 0.05, seed: int = 42) -> Tuple[float, float, float]:
    arr = np.asarray(data, float)
    if len(arr) == 0:
        return 0.0, 0.0, 0.0
    med = float(np.median(arr))
    rng = np.random.default_rng(seed)
    boot_meds = np.empty(num_bootstraps, dtype=float)
    n = len(arr)
    for b in range(num_bootstraps):
        sample = rng.choice(arr, size=n, replace=True)
        boot_meds[b] = np.median(sample)
    low = float(np.percentile(boot_meds, 100 * (alpha / 2)))
    high = float(np.percentile(boot_meds, 100 * (1 - alpha / 2)))
    return med, low, high


